     * 重置密码
     *
     * @param accountId
     */
    @Override
    public String resetPwd(Long accountId, UserDTO userDTO) {
        return externalMerchantService.resetPwd(accountId);
    }

    /**
     * 查询当前公司用户
     *
     * @param requestDTO
     * @param userDTO
     */
    @Override
    public PageInfo<AccountAuthVO> querySubAccounts(PageRequestDTO<MerchantSubAccountQueryDTO> requestDTO, UserDTO userDTO) {
        PageInfo<AccountVO> accountVOList =merchantAuthService.findByCompany(requestDTO, userDTO.getCompany(), userDTO.getAccountId());
        List<AccountAuthVO> accountAuthVOList = new ArrayList<>();
        for (AccountVO accountVO : accountVOList.getList()) {
            AccountAuthE accountAuthE = authRepository.getAccountAuthNoCache(accountVO.getAccountId(), false);
            accountAuthVOList.add(authAssembler.entity2Vo(accountAuthE));
        }
        PageInfo<AccountAuthVO> res = (PageInfo)accountVOList;
        res.setList(accountAuthVOList);
        return res;
    }


    /**
     * 校验账号角色
     */
    private void checkRolesInAccount(String accountId, List<String> roleCodes) {
        AccountAuthE accountAuthE = authRepository.getAccountAuthNoCache(accountId, false);
        for (String roleCode : roleCodes) {
            if (!accountAuthE.getAuthRoles().containsKey(roleCode)) {
                throw new BizException("账号无权分配此角色:"+roleCode);
            }
        }
    }
